t.script:
(function(){
  "use strict";
  function $(s,r){return (r||document).querySelector(s);}
  function $val(id,d){var el=$("#"+id);return el?el.value:d;}
  function uid(){return 'spw_'+Math.random().toString(36).slice(2,10)+'_'+Date.now().toString(36);}
  async function loadImage(src){return new Promise(function(res,rej){var i=new Image();i.onload=function(){res(i)};i.onerror=rej;i.src=src;});}
  function readAsDataURL(f){return new Promise(function(res,rej){var r=new FileReader();r.onload=function(){res(r.result)};r.onerror=rej;r.readAsDataURL(f);});}

  async function postJSON(url,p){
    try{
      const r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest"},credentials:"same-origin",body:JSON.stringify(p)});
      const t=await r.text(); let d=null; try{ d=JSON.parse(t);}catch(_){}
      return {ok:r.ok && !!d, data:d||{}};
    }catch(e){return {ok:false,data:{},err:String(e)};}
  }
  async function postForm(url,p){
    try{
      const fd=new FormData(); Object.keys(p||{}).forEach(k=>fd.append(k,p[k]));
      const r=await fetch(url,{method:"POST",body:fd,credentials:"same-origin"});
      const t=await r.text(); let d=null; try{ d=JSON.parse(t);}catch(_){}
      return {ok:r.ok, data:d||{}};
    }catch(e){return {ok:false,data:{},err:String(e)};}
  }

  function applyTransform(){
    var logo=$("#spw_logo_preview"), base=$("#spw_product_img"); if(!logo||!base) return;
    var size=parseInt($val("spw_size","100"),10),
        x=parseInt($val("spw_pos_x","0"),10),
        y=parseInt($val("spw_pos_y","10"),10),
        rot=parseInt($val("spw_rotation","0"),10);
    var bw=base.clientWidth, bh=base.clientHeight;
    var left=bw*(0.5+x/100), top=bh*(0.6+y/100);
    logo.style.position="absolute";
    logo.style.left=left+"px";
    logo.style.top=top+"px";
    logo.style.transform="translate(-50%,-50%) rotate("+rot+"deg)";
    logo.style.width=size+"px";
    logo.classList.remove("d-none");
    logo.style.opacity="1";
  }

  async function renderPNGDataURL(){
    var internal=$("#spw-base-img");
    var baseSrc=(internal&&internal.getAttribute("src"))||$val("spw_img_src","")||($("#spw_product_img")||{}).getAttribute("src");
    var baseIm=await loadImage(baseSrc);
    var c=document.createElement("canvas"), ctx=c.getContext("2d");
    c.width=baseIm.naturalWidth||baseIm.width; c.height=baseIm.naturalHeight||baseIm.height;
    ctx.drawImage(baseIm,0,0,c.width,c.height);

    var logo=$("#spw_logo_preview");
    if(logo && logo.src){
      var baseEl=$("#spw_product_img"),
          bw=baseEl.clientWidth, bh=baseEl.clientHeight,
          br=baseEl.getBoundingClientRect(), lr=logo.getBoundingClientRect();
      var cx=((lr.left+lr.width/2)-br.left)/bw*c.width;
      var cy=((lr.top+lr.height/2)-br.top)/bh*c.height;
      var wnorm=lr.width/bw, drawW=wnorm*c.width;
      var li=await loadImage(logo.src);
      var ratio=(li.naturalHeight||li.height)/(li.naturalWidth||li.width);
      var drawH=drawW*ratio;
      var rot=(parseInt($val("spw_rotation","0"),10)*Math.PI)/180;
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot);
      ctx.drawImage(li,-drawW/2,-drawH/2,drawW,drawH);
      ctx.restore();
    }
    return c.toDataURL("image/png");
  }

  async function addToCart(){
    const variantId=($val("spw_variant_id","")||"").trim();
    if(!variantId){ alert("Falta la variante del producto."); return; }
    const qty=parseInt($val("spw_qty","1")||"1",10)||1;
    const tech=(document.querySelector("input[name='spw_tech']:checked")||{}).value||"";
    const svgColor=(document.querySelector("input[name='spw_svg_color']:checked")||{}).value||"";
    const notes=($val("spw_notes","")||"").trim();
    const spw_token=uid();

    let png_b64="";
    try{
      const du=await renderPNGDataURL();
      png_b64 = du ? du.split("base64,")[1] : "";
      sessionStorage.setItem('spw_last_png', du || '');
      sessionStorage.setItem('spw_last_color', svgColor || '');
    }catch(_){}

    let r1 = await postForm("/spw/add_to_cart_meta_http", {
      variant_id: variantId,
      qty: String(qty),
      tech: tech,
      svg_color: svgColor,
      notes: notes,
      spw_token: spw_token
    });
    if(!(r1.ok && r1.data && r1.data.line_id)){
      r1 = await postJSON("/spw/add_to_cart_meta", {
        variant_id: parseInt(variantId,10),
        qty: qty,
        tech: tech,
        svg_color: svgColor,
        notes: notes,
        spw_token: spw_token
      });
    }
    if(!(r1.ok && r1.data && r1.data.line_id)){
      alert("No se pudo añadir.");
      return;
    }
    const lineId=r1.data.line_id;
    sessionStorage.setItem('spw_last_line_id', String(lineId));

    if(png_b64){
      const r2=await postJSON("/spw/attach_png", { line_id: lineId, png_b64: png_b64 });
      if(!r2.ok){ await postForm("/spw/attach_png_http", { line_id: lineId, png_b64: png_b64 }); }
    }
    window.location.href="/shop/cart?spw_line_id="+encodeURIComponent(lineId);
  }

  function init(){
    const inp=$("#spw_logo_input"), logo=$("#spw_logo_preview");
    if(inp){
      inp.addEventListener("change", async function(e){
        const f=e.target.files && e.target.files[0]; if(!f) return;
        const du=await readAsDataURL(f);
        logo.src=du; applyTransform();
      });
    }
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(function(id){
      const el=document.getElementById(id); if(el) el.addEventListener("input", applyTransform);
    });
    window.spwReset=function(){
      document.getElementById("spw_size").value=100;
      document.getElementById("spw_pos_x").value=0;
      document.getElementById("spw_pos_y").value=10;
      document.getElementById("spw_rotation").value=0;
      applyTransform();
    };
    const add=$("#spw_add_to_cart"); if(add){ add.addEventListener("click", addToCart); }
    const dl=$("#spw_download_png"); if(dl){
      dl.addEventListener("click", async function(){
        try{
          const du=await renderPNGDataURL();
          const a=document.createElement("a"); a.href=du; a.download="personalizacion.png";
          document.body.appendChild(a); a.click(); a.remove();
        }catch(_){ alert("No se pudo generar el PNG."); }
      });
    }
    applyTransform();
  }
  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();

xpath.script:
(function(){
  "use strict";
  if (!/\/shop\/cart/.test(location.pathname)) return;

  function q(s,r){return (r||document).querySelector(s);}
  function qa(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s));}

  function urlParam(name){
    try{ return new URL(location.href).searchParams.get(name); }catch(_){ return null; }
  }
  function parseLineIdFromHref(node){
    try{
      var a = (node.closest && node.closest('a[href*="line_id="]')) || (node.querySelector && node.querySelector('a[href*="line_id="]'));
      if(!a) return null;
      var u = new URL(a.getAttribute('href'), location.origin);
      return u.searchParams.get('line_id');
    }catch(_){ return null; }
  }
  function getLineId(line){
    if(!line) return null;
    var v = line.getAttribute('data-line-id')
      || ((q('input[name="line_id"]', line)||{}).value)
      || parseLineIdFromHref(line)
      || null;
    return v ? String(v) : null;
  }
  function findLines(){
    var sel = 'tr.js_cart_line, .o_wsale_cart_item, .card.js_cart_item, .o_cart_line';
    return qa(sel).filter(function(n){ return !!getLineId(n); });
  }
  function infoContainer(line){
    return q('.o_wsale_product_information', line)
        || q('.o_cart_product_info', line)
        || q('td.o_wsale_cart_description', line)
        || q('.media-body', line)
        || line;
  }
  function detectHexes(line){
    try{
      var cont = infoContainer(line);
      if(!cont) return [];
      var txt = (cont.textContent||'');
      var re = /#([0-9a-fA-F]{6})\b/g, m, arr=[];
      while((m=re.exec(txt))){ arr.push('#'+m[1].toUpperCase()); }
      return arr.length?arr:['#000000'];
    }catch(_){ return ['#000000']; }
  }
  function buildPreviewURL(lineId, idx){
    // URL estable (sin timestamp) para evitar tormenta de peticiones.
    return '/spw/line_preview/' + encodeURIComponent(lineId) + '.png?i=' + (idx+1);
  }

  function ensureWrap(line){
    var id = getLineId(line); if(!id) return null;
    var wrap = q('.spw-cart-block[data-line="'+id+'"]', line);
    if(!wrap){
      wrap = document.createElement('div');
      wrap.className = 'spw-cart-block';
      wrap.setAttribute('data-line', id);
      (infoContainer(line)||line).appendChild(wrap);
    }
    return wrap;
  }

  function renderLine(line){
    var id = getLineId(line); if(!id) return;
    var wrap = ensureWrap(line); if(!wrap) return;

    var colors = detectHexes(line);
    var target = Math.max(colors.length, 1);

    // Añadir solo las imágenes que falten; no borrar ni recrear.
    for (var i=1; i<=target; i++){
      if (!wrap.querySelector('img[data-spw="1"][data-i="'+i+'"]')){
        var im = new Image();
        im.alt = 'Personalización';
        im.loading = 'lazy';
        im.dataset.spw = '1';
        im.dataset.i = String(i);
        im.src = buildPreviewURL(id, i-1);
        wrap.appendChild(im);
      }
    }

    // Píldoras: solo si aún no existen.
    if (!wrap.querySelector('.spw-swatch')){
      colors.forEach(function(hex){
        var sw = document.createElement('span');
        sw.className = 'spw-swatch';
        sw.title = hex;
        sw.style.background = hex;
        wrap.appendChild(sw);
      });
    }
  }

  function inject(){
    var lines = findLines();

    // Eliminar bloques huérfanos
    qa('.spw-cart-block').forEach(function(n){
      var lid=n.getAttribute('data-line');
      var alive = lines.some(function(l){ return getLineId(l)===lid; });
      if(!alive) n.remove();
    });

    lines.forEach(renderLine);

    // Si venimos del customizador, mostrar la última imagen en memoria
    var wanted = urlParam('spw_line_id');
    if (wanted) {
      try{
        var lastId = sessionStorage.getItem('spw_last_line_id');
        var lastPng = sessionStorage.getItem('spw_last_png');
        var lastColor = sessionStorage.getItem('spw_last_color');
        if (lastId && lastPng && lastId === wanted) {
          var line = lines.find(function(l){ return getLineId(l) === wanted; });
          if (line) {
            var wrap = ensureWrap(line);
            if (wrap && !wrap.querySelector('img[data-spw-last="1"]')){
              var im=new Image();
              im.alt='Personalización';
              im.loading='eager';
              im.dataset.spw='1';
              im.dataset.spwLast='1';
              im.dataset.i='1';
              im.src=lastPng;
              wrap.prepend(im);
              if(lastColor && !wrap.querySelector('.spw-swatch')){
                var sw=document.createElement('span'); sw.className='spw-swatch'; sw.title=lastColor; sw.style.background=lastColor; wrap.appendChild(sw);
              }
            }
          }
        }
      }catch(_){}
      try{
        sessionStorage.removeItem('spw_last_line_id');
        sessionStorage.removeItem('spw_last_png');
        sessionStorage.removeItem('spw_last_color');
      }catch(_){}
    }
  }

  // Evitar múltiples observers
  if (!document.body.dataset.spwCartBound){
    document.body.dataset.spwCartBound = '1';
    inject();
    var root = q('.js_cart_lines') || q('.o_wsale_cart') || q('main') || document.body;
    if(window.MutationObserver && root){
      var ticking=false;
      var mo = new MutationObserver(function(){
        if (ticking) return;
        ticking = true;
        requestAnimationFrame(function(){ ticking=false; inject(); });
      });
      mo.observe(root, {childList:true, subtree:true});
    }
    // Reintento único por si el DOM tarda en montar
    setTimeout(inject, 400);
  }
})();
